// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.IdentityHashMap;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

class OwnedStringDiagnosticTest {
	@Test
	void typedDataKeepsExactTextAndEscapesWithoutAnExecutableRecipe() {
		var text = OwnedStringDiagnostic.builder()
				.append("x=")
				.append(17)
				.append('/')
				.append(Long.MIN_VALUE)
				.append(' ')
				.append(-0.0d)
				.append(' ')
				.append(true)
				.append(" ")
				.jsonString("a\"\n\u0001")
				.build();
		String value = text.get();
		assertEquals("x=17/-9223372036854775808 -0.0 true \"a\\\"\\n\\u0001\"", value);
		assertTrue(text.maximumRenderedCharacters() >= value.length());
	}

	@Test
	void unauditedSupplierIsRefusedWithoutInvocationAndOrdinaryApiStillWorks() {
		SingletonSet source = new SingletonSet();
		SingletonSet copy = new SingletonSet();
		AtomicInteger calls = new AtomicInteger();
		source.setStringMetricPlannedDeferred("optimizer.packedExplanation", () -> {
			calls.incrementAndGet();
			return "untrusted";
		});
		assertFalse(source.copyDetachedPlanningStateTo(copy, (key, value, target) -> false));
		assertEquals(0, calls.get());
		assertEquals("untrusted", source.getStringMetricPlanned("optimizer.packedExplanation"));
		assertEquals(1, calls.get());
	}

	@Test
	void aliasesHavePrivateWrappersAndFutureOutputIsReservedBeforeRendering() {
		SingletonSet source = new SingletonSet();
		var diagnostic = OwnedStringDiagnostic.builder().append("owned:").jsonString("\n".repeat(1000)).build();
		source.setStringMetricPlannedDeferred("one", diagnostic);
		source.setStringMetricPlannedDeferred("two", diagnostic);
		SingletonSet first = new SingletonSet();
		SingletonSet second = new SingletonSet();
		assertTrue(source.copyDetachedPlanningStateTo(first, (key, value, target) -> false));
		assertTrue(source.copyDetachedPlanningStateTo(second, (key, value, target) -> false));
		IdentityHashMap<Object, Long> memory = new IdentityHashMap<>();
		assertTrue(first.accountDetachedPlanningState((object, bytes) -> memory.putIfAbsent(object, bytes) == null,
				(key, value, account) -> false));
		assertTrue(memory.values().stream().mapToLong(Long::longValue).sum() >= 2L
				* diagnostic.maximumRenderedCharacters());
		String rendered = first.getStringMetricPlanned("one");
		assertSame(rendered, first.getStringMetricPlanned("two"));
		assertEquals(rendered, second.getStringMetricPlanned("two"));
		assertEquals(rendered, source.getStringMetricPlanned("one"));
	}
}
